INSERT INTO `posts` (`id`, `created_at`, `updated_at`, `author_id`, `category`, `content`, `title`) VALUES
  (1, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 34 DAY), '09:49:00'), @seed_now, 3, 'MEETING', '이번 주 신규 상담 6건의 예상 발주 시점과 다음 연락 일정을 담당자별로 확인합니다.', '주간 영업 파이프라인 점검'),
  (2, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 33 DAY), '11:23:00'), @seed_now, 1, 'NOTICE', '보증 만료 예정 장비부터 순차 방문합니다. 고객과 합의한 정지 가능 시간을 서비스 일정에 등록해 주세요.', '하반기 장비 정기 점검 일정 안내'),
  (3, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 32 DAY), '13:31:00'), @seed_now, 5, 'FREE', '전원 용량, 집진 배관, 장비 반입구 폭을 방문 전에 확인할 수 있도록 현장 체크리스트를 공유합니다.', '현장 방문 전 체크리스트 공유'),
  (4, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 31 DAY), '16:13:00'), @seed_now, 6, 'MEETING', '본체와 집진기 반입 순서, 지게차 대기 위치, 설치 당일 고객 담당자 역할을 확정합니다.', '미르온정밀 설치 동선 사전 검토'),
  (5, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 30 DAY), '10:28:00'), @seed_now, 1, 'NOTICE', '현장 작업 전 잠금장치와 보호구 점검 절차를 중심으로 안전교육을 진행합니다.', '서비스 엔지니어 안전교육 일정'),
  (6, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 29 DAY), '14:18:00'), @seed_now, 8, 'FREE', '오염 확인부터 교체 후 출력 시험까지 현장에서 자주 놓치는 순서를 정리했습니다.', '레이저 보호창 교체 요령'),
  (7, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 28 DAY), '09:41:00'), @seed_now, 9, 'MEETING', '계약 단계별 선수금과 잔금 예정일을 대조하고 지연 가능 건의 고객 연락 계획을 정리합니다.', '월간 계약·입금 예정 점검'),
  (8, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 27 DAY), '14:39:00'), @seed_now, 1, 'NOTICE', '기술지원 당번과 부품 출고 담당을 확인하고 긴급 장애 접수 시 인계 순서를 공유합니다.', '휴가철 비상 연락 체계 안내'),
  (9, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 26 DAY), '11:10:00'), @seed_now, 11, 'FREE', '출발 전 타이어와 소모품을 확인하고 장비별 공구 상자가 실렸는지 함께 점검해 주세요.', '장거리 현장 방문 차량 점검 팁'),
  (10, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 25 DAY), '17:16:00'), @seed_now, 2, 'MEETING', '가공 소재 두께와 자동 로딩 범위를 기준으로 최종 옵션, 교육 일정, 검수 조건을 확정합니다.', '솔누리금속 납품 전 사양 확정'),
  (11, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 24 DAY), '14:55:00'), @seed_now, 1, 'NOTICE', '현장 점검표와 설치 확인서의 고객 확인란을 통일했습니다. 새 양식은 다음 방문부터 사용해 주세요.', '기술 문서 표준 양식 개정 안내'),
  (12, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 23 DAY), '13:08:00'), @seed_now, 4, 'FREE', '결정 사항, 미확정 항목, 다음 담당자와 기한이 한눈에 보이도록 작성한 회의록 예시를 공유합니다.', '고객 응대 회의록 작성 예시'),
  (13, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 22 DAY), '11:55:00'), @seed_now, 5, 'MEETING', '90일 안에 보증이 끝나는 장비를 확인하고 사전 점검과 유지보수 계약 안내 대상을 선정합니다.', '보증 만료 예정 고객 대응 회의'),
  (14, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 21 DAY), '11:16:00'), @seed_now, 1, 'NOTICE', '장비 가동 구역과 상담 구역을 분리하고 방문 고객의 보호구 착용과 사진 촬영 기준을 안내합니다.', '고객 시연회 운영 동선 공지'),
  (15, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 20 DAY), '11:11:00'), @seed_now, 7, 'FREE', '교통·숙박 영수증을 출장 건별로 묶고 누락 여부를 확인하는 간단한 정리 순서를 공유합니다.', '출장비 증빙 정리 방법'),
  (16, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 19 DAY), '11:40:00'), @seed_now, 8, 'MEETING', '보호창, 노즐, 센서의 최근 사용량을 기준으로 안전 재고와 다음 발주 수량을 검토합니다.', '서비스 예비부품 재고 점검'),
  (17, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 18 DAY), '12:43:00'), @seed_now, 1, 'NOTICE', '방문자 명단과 차량 정보를 전날까지 전달하고 반입 장비의 중량표를 함께 준비해 주세요.', '장비 반입 시 출입 절차 안내'),
  (18, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 17 DAY), '14:20:00'), @seed_now, 10, 'FREE', '초보 작업자가 소재 배치와 공정 순서를 연습할 수 있는 단계별 교육 자료를 모았습니다.', '네스팅 교육 자료 추천'),
  (19, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 16 DAY), '16:31:00'), @seed_now, 11, 'MEETING', '산업전과 홈페이지에서 유입된 상담을 관심 품목과 도입 시점으로 나누어 후속 연락 우선순위를 정합니다.', '신규 영업 접점 후속 조치 점검'),
  (20, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 15 DAY), '10:15:00'), @seed_now, 1, 'NOTICE', '계약서와 설치 확인서는 지정 폴더에 보관하고 임시 사본은 검토 완료 후 정리해 주세요.', '문서 보관 기준 정기 점검'),
  (21, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 14 DAY), '13:34:00'), @seed_now, 3, 'FREE', '고객 정보가 노출되지 않도록 촬영 범위를 조정하고 장비 상태를 재현할 수 있는 필수 각도를 정리했습니다.', '현장 사진 촬영 기준 공유'),
  (22, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 13 DAY), '08:26:00'), @seed_now, 4, 'MEETING', '원점 센서 알람과 집진기 인터록 사례의 진단 순서, 고객 안내, 재발 방지 항목을 함께 검토합니다.', '기술지원 사례 회고'),
  (23, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 12 DAY), '12:53:00'), @seed_now, 1, 'NOTICE', '퇴사자와 담당 변경 정보를 확인해 고객 연락처와 영업 인계 기록을 최신 상태로 유지해 주세요.', '분기 연락처 정확성 점검 안내'),
  (24, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 11 DAY), '08:53:00'), @seed_now, 6, 'FREE', '시운전 결과, 교육 참석자, 소모품 위치, 다음 점검 예정일을 고객에게 인계할 때 확인할 항목입니다.', '설치 완료 후 고객 인계 항목'),
  (25, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 10 DAY), '14:28:00'), @seed_now, 7, 'MEETING', '동시 설치가 예정된 현장의 인력, 운송, 부품 준비 상태를 대조하고 충돌 일정을 조정합니다.', '다음 달 설치 일정 리스크 점검'),
  (26, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 9 DAY), '11:36:00'), @seed_now, 1, 'NOTICE', '진행 중인 설치와 서비스 건의 주 담당·대체 담당 연락처를 연휴 전에 다시 확인해 주세요.', '연휴 전 고객 연락망 확인'),
  (27, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 8 DAY), '09:18:00'), @seed_now, 9, 'FREE', '노트북 어댑터, 통신 케이블, 측정기, 보호구처럼 자주 빠지는 준비물을 한 장으로 정리했습니다.', '출장 준비물 체크리스트'),
  (28, TIMESTAMP(DATE_SUB(@seed_today, INTERVAL 7 DAY), '16:35:00'), @seed_now, 10, 'MEETING', '계약 진행률과 검수 일정을 기준으로 이번 달 인식 가능 매출과 수금 후속 조치를 최종 점검합니다.', '월말 매출 전망 및 수금 계획');
