UPDATE contracts c JOIN (SELECT id, CONCAT('CT', YEAR(contract_date), '-', LPAD(ROW_NUMBER() OVER (PARTITION BY YEAR(contract_date) ORDER BY contract_date, id), 3, '0')) AS generated_no FROM contracts) x ON x.id=c.id SET c.contract_no=x.generated_no;






UPDATE after_services a JOIN (SELECT id, CONCAT('AS', YEAR(received_date), '-', LPAD(ROW_NUMBER() OVER (PARTITION BY YEAR(received_date) ORDER BY received_date, id), 4, '0')) AS generated_no FROM after_services) x ON x.id=a.id SET a.receipt_no=x.generated_no;










